def maxProfitK(k, prices):
    n = len(prices)
    if k == 0 or n < 2:
        return 0
    if k >= n // 2:
        return sum(max(0, prices[i] - prices[i - 1]) for i in range(1, n))
    NEG = -10 ** 9
    buy = [NEG] * (k + 1)
    sell = [0] * (k + 1)
    for p in prices:
        for j in range(1, k + 1):
            if sell[j - 1] - p > buy[j]:
                buy[j] = sell[j - 1] - p
            if buy[j] + p > sell[j]:
                sell[j] = buy[j] + p
    return sell[k]
